package bottlesong

import (
	"fmt"
	"strings"
)

// Recite returns the lyrics of the "Ten Green Bottles" song, starting with
// startBottles bottles and singing takeDown verses. Verses are separated by
// a blank line.
func Recite(startBottles, takeDown int) []string {
	var verses []string
	for n := startBottles; n > startBottles-takeDown; n-- {
		verses = append(verses, verse(n)...)
	}
	return verses
}

// verse returns the four lines of the verse for n bottles.
func verse(n int) []string {
	return []string{
		fmt.Sprintf("%s green bottles hanging on the wall,", Title(bottleWord(n))),
		fmt.Sprintf("%s green bottles hanging on the wall,", Title(bottleWord(n))),
		"And if one green bottle should accidentally fall,",
		fmt.Sprintf("There'll be %s green bottle%s hanging on the wall.", bottleWord(n-1), bottleSuffix(n-1)),
	}
}

// bottleWord returns the number of bottles as a word, e.g. "three".
func bottleWord(n int) string {
	switch n {
	case 0:
		return "no"
	case 1:
		return "one"
	case 2:
		return "two"
	case 3:
		return "three"
	case 4:
		return "four"
	case 5:
		return "five"
	case 6:
		return "six"
	case 7:
		return "seven"
	case 8:
		return "eight"
	case 9:
		return "nine"
	case 10:
		return "ten"
	default:
		return strings.ToLower(fmt.Sprintf("%d", n))
	}
}

// bottleSuffix returns the plural suffix for the bottle count.
func bottleSuffix(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

